-- 0. limpeza (inclui as tabelas do script de teste anterior)
DROP VIEW IF EXISTS vw_estoque, vw_parcela, vw_chamado, vw_comissao, vw_despesa CASCADE;
DROP TABLE IF EXISTS sessao, parametro, despesa, chamado, cobranca, parcela, contrato, negociacao_historico, negociacao, moto, cliente, log_acesso, usuario, ferias, funcionario CASCADE;

-- 1. estrutura (convertida de banco/schema.sql)
CREATE TABLE IF NOT EXISTS funcionario (
  id                   integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nome                 TEXT    NOT NULL,
  cpf                  TEXT    NOT NULL UNIQUE,
  cargo                TEXT    NOT NULL,
  setor                TEXT    NOT NULL,
  data_admissao        TEXT    NOT NULL,
  data_desligamento    TEXT,
  salario              numeric    NOT NULL DEFAULT 0,
  percentual_comissao  numeric    NOT NULL DEFAULT 0,
  meta_mensal          INTEGER NOT NULL DEFAULT 0,
  situacao             TEXT    NOT NULL DEFAULT 'ativo'
                       CHECK (situacao IN ('ativo','ferias','desligado'))
);
CREATE TABLE IF NOT EXISTS ferias (
  id              integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  funcionario_id  INTEGER NOT NULL REFERENCES funcionario(id),
  data_inicio     TEXT    NOT NULL,
  data_fim        TEXT    NOT NULL,
  situacao        TEXT    NOT NULL DEFAULT 'programada'
                  CHECK (situacao IN ('programada','em_gozo','concluida'))
);
CREATE TABLE IF NOT EXISTS usuario (
  id              integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  email           TEXT    NOT NULL UNIQUE,
  senha_hash      TEXT    NOT NULL,
  perfil          TEXT    NOT NULL CHECK (perfil IN ('dono','funcionario')),
  funcionario_id  INTEGER REFERENCES funcionario(id),
  ativo           INTEGER NOT NULL DEFAULT 1,
  criado_em       TEXT    NOT NULL DEFAULT (to_char((now() AT TIME ZONE 'America/Sao_Paulo'), 'YYYY-MM-DD HH24:MI:SS'))
);
CREATE TABLE IF NOT EXISTS log_acesso (
  id          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  usuario_id  INTEGER REFERENCES usuario(id),
  email       TEXT    NOT NULL,
  sucesso     INTEGER NOT NULL,
  momento     TEXT    NOT NULL DEFAULT (to_char((now() AT TIME ZONE 'America/Sao_Paulo'), 'YYYY-MM-DD HH24:MI:SS'))
);
CREATE TABLE IF NOT EXISTS cliente (
  id           integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nome         TEXT NOT NULL,
  cpf          TEXT NOT NULL UNIQUE,
  telefone     TEXT NOT NULL,
  email        TEXT,
  cidade       TEXT,
  origem       TEXT,
  vendedor_id  INTEGER REFERENCES funcionario(id),
  observacao   TEXT,
  criado_em    TEXT NOT NULL DEFAULT (to_char((now() AT TIME ZONE 'America/Sao_Paulo'), 'YYYY-MM-DD HH24:MI:SS'))
);
CREATE TABLE IF NOT EXISTS moto (
  id           integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  codigo       TEXT    NOT NULL UNIQUE,
  marca        TEXT    NOT NULL,
  modelo       TEXT    NOT NULL,
  ano          INTEGER NOT NULL,
  cor          TEXT,
  placa        TEXT,
  chassi       TEXT,
  km           INTEGER NOT NULL DEFAULT 0,
  tipo         TEXT    NOT NULL DEFAULT 'seminova' CHECK (tipo IN ('nova','seminova')),
  custo        numeric    NOT NULL DEFAULT 0,
  preco_venda  numeric    NOT NULL DEFAULT 0,
  data_entrada TEXT    NOT NULL,
  data_saida   TEXT,
  situacao     TEXT    NOT NULL DEFAULT 'disponivel'
               CHECK (situacao IN ('disponivel','reservada','preparacao','vendida'))
);
CREATE TABLE IF NOT EXISTS negociacao (
  id              integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  cliente_id      INTEGER NOT NULL REFERENCES cliente(id),
  moto_id         INTEGER REFERENCES moto(id),
  vendedor_id     INTEGER NOT NULL REFERENCES funcionario(id),
  etapa           TEXT    NOT NULL DEFAULT 'lead'
                  CHECK (etapa IN ('lead','contato','proposta','financiamento','fechada','perdida')),
  valor_negociado numeric    NOT NULL DEFAULT 0,
  motivo_perda    TEXT,
  criado_em       TEXT    NOT NULL DEFAULT (to_char((now() AT TIME ZONE 'America/Sao_Paulo'), 'YYYY-MM-DD HH24:MI:SS')),
  atualizado_em   TEXT    NOT NULL DEFAULT (to_char((now() AT TIME ZONE 'America/Sao_Paulo'), 'YYYY-MM-DD HH24:MI:SS'))
);
CREATE TABLE IF NOT EXISTS negociacao_historico (
  id             integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  negociacao_id  INTEGER NOT NULL REFERENCES negociacao(id),
  etapa_de       TEXT,
  etapa_para     TEXT    NOT NULL,
  usuario_id     INTEGER REFERENCES usuario(id),
  responsavel    TEXT,
  momento        TEXT    NOT NULL DEFAULT (to_char((now() AT TIME ZONE 'America/Sao_Paulo'), 'YYYY-MM-DD HH24:MI:SS'))
);
CREATE TABLE IF NOT EXISTS contrato (
  id              integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  numero          TEXT    NOT NULL UNIQUE,
  negociacao_id   INTEGER REFERENCES negociacao(id),
  cliente_id      INTEGER NOT NULL REFERENCES cliente(id),
  moto_id         INTEGER NOT NULL REFERENCES moto(id),
  vendedor_id     INTEGER NOT NULL REFERENCES funcionario(id),
  forma_pagamento TEXT    NOT NULL CHECK (forma_pagamento IN ('avista','financiado','entrada_parcelas')),
  valor_total     numeric    NOT NULL,
  valor_entrada   numeric    NOT NULL DEFAULT 0,
  qtd_parcelas    INTEGER NOT NULL DEFAULT 1,
  banco           TEXT,
  data_emissao    TEXT    NOT NULL DEFAULT (to_char((now() AT TIME ZONE 'America/Sao_Paulo'), 'YYYY-MM-DD')),
  situacao        TEXT    NOT NULL DEFAULT 'ativo'
                  CHECK (situacao IN ('ativo','quitado','cancelado')),
  cancelado_por   INTEGER REFERENCES usuario(id),
  motivo_cancelamento TEXT
);
CREATE TABLE IF NOT EXISTS parcela (
  id             integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  contrato_id    INTEGER NOT NULL REFERENCES contrato(id),
  numero         INTEGER NOT NULL,
  valor          numeric    NOT NULL,
  vencimento     TEXT    NOT NULL,
  data_pagamento TEXT,
  situacao       TEXT    NOT NULL DEFAULT 'aberta'
                 CHECK (situacao IN ('aberta','paga','cancelada')),
  UNIQUE (contrato_id, numero)
);
CREATE TABLE IF NOT EXISTS cobranca (
  id           integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  parcela_id   INTEGER NOT NULL REFERENCES parcela(id),
  tipo         TEXT    NOT NULL
               CHECK (tipo IN ('lembrete','segunda_via','contato','negativacao')),
  canal        TEXT,
  observacao   TEXT,
  autorizado_por INTEGER REFERENCES usuario(id),
  momento      TEXT    NOT NULL DEFAULT (to_char((now() AT TIME ZONE 'America/Sao_Paulo'), 'YYYY-MM-DD HH24:MI:SS'))
);
CREATE TABLE IF NOT EXISTS chamado (
  id              integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  numero          TEXT    NOT NULL UNIQUE,
  cliente_id      INTEGER NOT NULL REFERENCES cliente(id),
  moto_id         INTEGER REFERENCES moto(id),
  assunto         TEXT    NOT NULL,
  descricao       TEXT,
  responsavel_id  INTEGER REFERENCES funcionario(id),
  data_abertura   TEXT    NOT NULL DEFAULT (to_char((now() AT TIME ZONE 'America/Sao_Paulo'), 'YYYY-MM-DD')),
  ultima_movimentacao TEXT NOT NULL DEFAULT (to_char((now() AT TIME ZONE 'America/Sao_Paulo'), 'YYYY-MM-DD')),
  data_conclusao  TEXT,
  situacao        TEXT    NOT NULL DEFAULT 'andamento'
                  CHECK (situacao IN ('andamento','resolvido'))
);
CREATE TABLE IF NOT EXISTS despesa (
  id             integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  descricao      TEXT    NOT NULL,
  categoria      TEXT    NOT NULL DEFAULT 'outros'
                 CHECK (categoria IN ('aluguel','energia','agua','internet','telefone',
                                      'impostos','contabilidade','marketing','manutencao',
                                      'seguro','outros')),
  valor          numeric    NOT NULL,
  vencimento     TEXT    NOT NULL,
  data_pagamento TEXT,
  recorrente     INTEGER NOT NULL DEFAULT 0,
  observacao     TEXT,
  situacao       TEXT    NOT NULL DEFAULT 'aberta'
                 CHECK (situacao IN ('aberta','paga','cancelada'))
);
CREATE TABLE IF NOT EXISTS parametro (
  chave      TEXT PRIMARY KEY,
  valor      TEXT NOT NULL,
  descricao  TEXT
);
CREATE INDEX IF NOT EXISTS ix_cliente_vendedor    ON cliente (vendedor_id);
CREATE INDEX IF NOT EXISTS ix_moto_situacao       ON moto (situacao);
CREATE INDEX IF NOT EXISTS ix_negociacao_etapa    ON negociacao (etapa);
CREATE INDEX IF NOT EXISTS ix_negociacao_vendedor ON negociacao (vendedor_id);
CREATE INDEX IF NOT EXISTS ix_parcela_vencimento  ON parcela (vencimento, situacao);
CREATE INDEX IF NOT EXISTS ix_parcela_contrato    ON parcela (contrato_id);
CREATE INDEX IF NOT EXISTS ix_contrato_emissao    ON contrato (data_emissao);
CREATE INDEX IF NOT EXISTS ix_chamado_situacao    ON chamado (situacao);
CREATE INDEX IF NOT EXISTS ix_despesa_vencimento  ON despesa (vencimento, situacao);
CREATE INDEX IF NOT EXISTS ix_cliente_nome        ON cliente (nome);
CREATE INDEX IF NOT EXISTS ix_moto_codigo         ON moto (codigo);
CREATE INDEX IF NOT EXISTS ix_contrato_numero     ON contrato (numero);
DROP VIEW IF EXISTS vw_estoque;
CREATE VIEW vw_estoque WITH (security_invoker = true) AS
SELECT
  m.*,
  CAST(((NULLIF(COALESCE(m.data_saida, to_char((now() AT TIME ZONE 'America/Sao_Paulo'), 'YYYY-MM-DD')), ''))::timestamp)::date - ((NULLIF(m.data_entrada, ''))::timestamp)::date AS INTEGER) AS dias_patio,
  CASE
    WHEN m.situacao <> 'vendida'
     AND ((NULLIF(to_char((now() AT TIME ZONE 'America/Sao_Paulo'), 'YYYY-MM-DD'), ''))::timestamp)::date - ((NULLIF(m.data_entrada, ''))::timestamp)::date > 90 THEN 1
    ELSE 0
  END AS parada_90_dias,
  (m.preco_venda - m.custo) AS margem
FROM moto m;
DROP VIEW IF EXISTS vw_parcela;
CREATE VIEW vw_parcela WITH (security_invoker = true) AS
SELECT
  p.*,
  c.numero        AS contrato_numero,
  c.cliente_id,
  cl.nome         AS cliente_nome,
  cl.telefone     AS cliente_telefone,
  CASE
    WHEN p.situacao = 'paga'      THEN 'paga'
    WHEN p.situacao = 'cancelada' THEN 'cancelada'
    WHEN to_char((NULLIF(p.vencimento, ''))::timestamp, 'YYYY-MM-DD') < to_char((now() AT TIME ZONE 'America/Sao_Paulo'), 'YYYY-MM-DD') THEN 'vencida'
    ELSE 'aberta'
  END AS situacao_real,
  CAST(((NULLIF(to_char((now() AT TIME ZONE 'America/Sao_Paulo'), 'YYYY-MM-DD'), ''))::timestamp)::date - ((NULLIF(p.vencimento, ''))::timestamp)::date AS INTEGER) AS dias_atraso
FROM parcela p
JOIN contrato c ON c.id = p.contrato_id
JOIN cliente  cl ON cl.id = c.cliente_id
WHERE c.situacao <> 'cancelado';
DROP VIEW IF EXISTS vw_chamado;
CREATE VIEW vw_chamado WITH (security_invoker = true) AS
SELECT
  ch.*,
  cl.nome AS cliente_nome,
  f.nome  AS responsavel_nome,
  m.codigo AS moto_codigo,
  m.modelo AS moto_modelo,
  CASE
    WHEN ch.situacao = 'resolvido' THEN 'resolvido'
    WHEN ((NULLIF(to_char((now() AT TIME ZONE 'America/Sao_Paulo'), 'YYYY-MM-DD'), ''))::timestamp)::date - ((NULLIF(ch.ultima_movimentacao, ''))::timestamp)::date > 5 THEN 'atrasado'
    ELSE 'andamento'
  END AS situacao_real
FROM chamado ch
JOIN cliente cl      ON cl.id = ch.cliente_id
LEFT JOIN funcionario f ON f.id = ch.responsavel_id
LEFT JOIN moto m     ON m.id = ch.moto_id;
DROP VIEW IF EXISTS vw_comissao;
CREATE VIEW vw_comissao WITH (security_invoker = true) AS
SELECT
  c.vendedor_id,
  f.nome                          AS vendedor_nome,
  f.percentual_comissao,
  to_char((NULLIF(c.data_emissao, ''))::timestamp, 'YYYY-MM') AS competencia,
  COUNT(*)                        AS vendas,
  SUM(c.valor_total)              AS faturamento,
  ROUND(SUM(c.valor_total) * f.percentual_comissao / 100.0, 2) AS comissao
FROM contrato c
JOIN funcionario f ON f.id = c.vendedor_id
WHERE c.situacao <> 'cancelado'
  AND EXISTS (
        SELECT 1 FROM parcela p
        WHERE p.contrato_id = c.id AND p.numero = 1 AND p.situacao = 'paga'
      )
GROUP BY c.vendedor_id, f.nome, f.percentual_comissao, competencia;
DROP VIEW IF EXISTS vw_despesa;
CREATE VIEW vw_despesa WITH (security_invoker = true) AS
SELECT
  d.*,
  CASE
    WHEN d.situacao = 'paga'      THEN 'paga'
    WHEN d.situacao = 'cancelada' THEN 'cancelada'
    WHEN to_char((NULLIF(d.vencimento, ''))::timestamp, 'YYYY-MM-DD') < to_char((now() AT TIME ZONE 'America/Sao_Paulo'), 'YYYY-MM-DD') THEN 'vencida'
    ELSE 'aberta'
  END AS situacao_real,
  CAST(((NULLIF(to_char((now() AT TIME ZONE 'America/Sao_Paulo'), 'YYYY-MM-DD'), ''))::timestamp)::date - ((NULLIF(d.vencimento, ''))::timestamp)::date AS INTEGER) AS dias_atraso,
  to_char((NULLIF(d.vencimento, ''))::timestamp, 'YYYY-MM') AS competencia
FROM despesa d;

-- 2. sessoes de login (a Vercel nao guarda nada na memoria entre acessos)
CREATE TABLE sessao (
  token      text   PRIMARY KEY,
  usuario    text   NOT NULL,
  expira_em  bigint NOT NULL
);

