-- 4. protecao: com RLS ligado e sem POLICY, a chave publica do Supabase
--    nao le nem grava nada. Quem acessa o banco e so o servidor do
--    sistema na Vercel, pela DATABASE_URL (que nunca vai para o codigo).
ALTER TABLE funcionario ENABLE ROW LEVEL SECURITY;
ALTER TABLE ferias ENABLE ROW LEVEL SECURITY;
ALTER TABLE usuario ENABLE ROW LEVEL SECURITY;
ALTER TABLE log_acesso ENABLE ROW LEVEL SECURITY;
ALTER TABLE cliente ENABLE ROW LEVEL SECURITY;
ALTER TABLE moto ENABLE ROW LEVEL SECURITY;
ALTER TABLE negociacao ENABLE ROW LEVEL SECURITY;
ALTER TABLE negociacao_historico ENABLE ROW LEVEL SECURITY;
ALTER TABLE contrato ENABLE ROW LEVEL SECURITY;
ALTER TABLE parcela ENABLE ROW LEVEL SECURITY;
ALTER TABLE cobranca ENABLE ROW LEVEL SECURITY;
ALTER TABLE chamado ENABLE ROW LEVEL SECURITY;
ALTER TABLE despesa ENABLE ROW LEVEL SECURITY;
ALTER TABLE parametro ENABLE ROW LEVEL SECURITY;
ALTER TABLE sessao ENABLE ROW LEVEL SECURITY;

-- 5. conferencia
SELECT 'tabelas' AS item, count(*) AS total FROM pg_tables WHERE schemaname = 'public'
UNION ALL SELECT 'clientes', count(*) FROM cliente
UNION ALL SELECT 'motos', count(*) FROM moto;
